#include <stdio.h>
#include <stdlib.h>

long fib(int n) {
    static long memo[100] = {0};
    static int computed[100] = {0};
    if (n < 0) {
        printf("NEGATIVE\n");
        exit(1);
    }
    if (n > 92) {
        printf("OUT_OF_RANGE\n");
        exit(1);
    }
    if (computed[n]) {
        return memo[n];
    }
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 1;
    }
    long result = fib(n-1) + fib(n-2);
    memo[n] = result;
    computed[n] = 1;
    return result;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 1;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        printf("BAD_INPUT\n");
        return 1;
    }
    printf("%lld\n", fib(n));
    return 0;
}
